{"code":"def transform(grid):
    # Keep one representative (the first) from every run of identical rows.
    rows=[]
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])
    # Then keep one representative from every run of identical columns.
    if not rows:
        return []
    w=len(rows[0])
    keep=[]
    for j in range(w):
        col=[r[j] for r in rows]
        if not keep or col != [r[keep[-1]] for r in rows]:
            keep.append(j)
    return [[row[j] for j in keep] for row in rows]"}

