    # Keep the first row of each consecutive run of identical rows.
    rows=[]
    for row in grid:
        if not rows or row != rows[-1]:
            rows.append(row[:])
    # Then keep the first column of each consecutive run of identical columns.
    if not rows:
        return []
    out=[]
    for r in rows:
        nr=[]
        for j in range(len(r)):
